const __helpers = this.helpers;
async function __req(opts) { return __helpers.httpRequest({ ...opts, returnFullResponse: false }); }
const digest = await __req({ method: 'GET', url: 'https://controlcenter.krishraja.com/api/tasks-inbox/digest', json: true });
const counts = (digest && digest.counts) || {};
const total = digest && digest.total || 0;
const lines = [
  `Inbox digest (last 7d): ${total} dropped.`,
  `  routed: ${counts.in_flight || 0}, needs_krish: ${counts.needs_krish || 0}, done: ${counts.done || 0}`,
  `  raw/classifying: ${(counts.raw || 0) + (counts.classifying || 0)}, needs_clarification: ${counts.needs_clarification || 0}`,
  `  archived: ${counts.archived || 0}, failed: ${counts.failed || 0}`,
].join('\n');
return [{ json: { ok: true, telegram_text: lines, total, counts } }];
